/* @autogenerated */
import type { WorkBook } from 'xlsx';

/** Plantilla en blanco: cabeceras de la hoja de datos y filas de la hoja de instrucciones. */
export interface ImportTemplate {
  /** Nombre de la hoja que se rellena. */
  dataSheet: string;
  headers: string[];
  /** Nombre de la hoja con la ayuda de cada columna. */
  helpSheet: string;
  /** Filas de la ayuda; la primera es su cabecera. */
  help: string[][];
}

/** Ancho de columna (en caracteres) para que se lea cada texto sin ajustarla a mano. */
const width = (rows: string[][], index: number) =>
  Math.min(60, Math.max(12, ...rows.map((row) => (row[index] ?? '').length + 2)));

/** Libro con la hoja de datos (solo cabeceras) en primer lugar y la de instrucciones después. */
export async function buildTemplate(template: ImportTemplate): Promise<WorkBook> {
  const XLSX = await import('xlsx');
  const book = XLSX.utils.book_new();
  const data = XLSX.utils.aoa_to_sheet([template.headers]);
  data['!cols'] = template.headers.map((_, index) => ({ wch: width([template.headers], index) }));
  XLSX.utils.book_append_sheet(book, data, sheetName(template.dataSheet));
  const help = XLSX.utils.aoa_to_sheet(template.help);
  help['!cols'] = (template.help[0] ?? []).map((_, index) => ({ wch: width(template.help, index) }));
  XLSX.utils.book_append_sheet(book, help, sheetName(template.helpSheet));
  return book;
}

/** Genera la plantilla y la descarga como `fileName`. */
export async function downloadTemplate(fileName: string, template: ImportTemplate): Promise<void> {
  const XLSX = await import('xlsx');
  XLSX.writeFile(await buildTemplate(template), fileName);
}

/** Excel limita el nombre de hoja a 31 caracteres y no admite `: \ / ? * [ ]`. */
function sheetName(name: string): string {
  return name.replace(/[:\\/?*[\]]/g, ' ').substring(0, 31);
}
